    public static void test_climain(Object capfd) {
        /* test arguments and main CLI entrypoint */
        // exit status required: 0
        // Windows platforms
        if (os.name == "nt") {
            var trafilatura_bin = path.join(sys.prefix, "Scripts", "trafilatura");
        // other platforms
        } else {
            trafilatura_bin = "trafilatura";
        }
        // help display
        assert subprocess.run(List.of(trafilatura_bin, "--help"), /* check = */ true).returncode == 0;
        // piped input
        var empty_input = "<html><body><article>" + "<p>ABC</p>".repeat(100) + "</article></body></html>";
        var result = subprocess.run(List.of(trafilatura_bin), /* input = */ empty_input, /* check = */ true);
        assert result.returncode == 0;
        var captured = capfd.readouterr();
        assert captured.out.trim().endsWith("ABC");
        // input directory walking and processing
        var env = os.environ.copy() /* shallow copy */;
        if (os.name == "nt") {
            // Force encoding to utf-8 for Windows (seem to be a problem only in GitHub Actions)
            env.put("PYTHONIOENCODING", "utf-8");
        }
        assert subprocess.run(List.of(trafilatura_bin, "--input-dir", RESOURCES_DIR), /* env = */ env, /* check = */ true).returncode == 0;
        // compressed file
        try (var inputf = new FileInputStream(path.join(RESOURCES_DIR, "webpage.html.gz"))) { // with
            var compressed_input = inputf.read();
        }
        assert subprocess.run(List.of(trafilatura_bin), /* input = */ compressed_input, /* check = */ true).returncode == 0;
        captured = capfd.readouterr();
        assert captured.out.trim().endsWith("in deep-red West Virginia.");
    }

